    // Per-kind walkers, indexed by NodeKind; each returns the id left in the slot. Padded to 256 entries.
    private static readonly delegate*<AstTransformer, JsAst, int, int, int, int>* s_walkers = CreateWalkers();

    private static delegate*<AstTransformer, JsAst, int, int, int, int>* CreateWalkers()
    {
        var table = (delegate*<AstTransformer, JsAst, int, int, int, int>*)NativeMemory.Alloc(256, (nuint)sizeof(nint));
        for (int i = 0; i < 256; i++) table[i] = &WalkNone;
        table[(int)NodeKind.Program] = &WalkProgram;
        table[(int)NodeKind.ArrayLiteral] = &WalkArrayLiteral;
        table[(int)NodeKind.ArrowFunctionLiteral] = &WalkArrowFunctionLiteral;
        table[(int)NodeKind.AssignExpression] = &WalkAssignExpression;
        table[(int)NodeKind.AwaitExpression] = &WalkAwaitExpression;
        table[(int)NodeKind.BigIntLiteral] = &WalkBigIntLiteral;
        table[(int)NodeKind.BinaryExpression] = &WalkBinaryExpression;
        table[(int)NodeKind.BooleanLiteral] = &WalkBooleanLiteral;
        table[(int)NodeKind.CallExpression] = &WalkCallExpression;
        table[(int)NodeKind.ClassLiteral] = &WalkClassLiteral;
        table[(int)NodeKind.ConditionalExpression] = &WalkConditionalExpression;
        table[(int)NodeKind.FunctionLiteral] = &WalkFunctionLiteral;
        table[(int)NodeKind.Identifier] = &WalkIdentifier;
        table[(int)NodeKind.InvalidExpression] = &WalkInvalidExpression;
        table[(int)NodeKind.LogicalExpression] = &WalkLogicalExpression;
        table[(int)NodeKind.MemberExpression] = &WalkMemberExpression;
        table[(int)NodeKind.MetaProperty] = &WalkMetaProperty;
        table[(int)NodeKind.NewExpression] = &WalkNewExpression;
        table[(int)NodeKind.NullLiteral] = &WalkNullLiteral;
        table[(int)NodeKind.NumberLiteral] = &WalkNumberLiteral;
        table[(int)NodeKind.ObjectLiteral] = &WalkObjectLiteral;
        table[(int)NodeKind.Optional] = &WalkOptional;
        table[(int)NodeKind.OptionalChain] = &WalkOptionalChain;
