    /// <summary>Transforms node <paramref name="id"/> (non-zero) in slot <paramref name="code"/> of <paramref name="owner"/>; returns the id now in that slot.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int Walk(AstTransformer v, JsAst ast, int id, int owner, int code)
    {
        NodeKind kind = ast._nodes[id].Kind;
        if (kind == NodeKind.Identifier)
            return v.Ov((int)NodeKind.Identifier) ? v.CallVisitIdentifier(ast, id, owner, code) : id;
        if (v.Skip(kind)) return id;
        return s_walkers[(int)kind](v, ast, id, owner, code);
    }

    private static int WalkNone(AstTransformer v, JsAst ast, int id, int owner, int code) => id;

    /// <summary>Transforms node <paramref name="id"/> (non-zero) as a child of static type <typeparamref name="T"/> that has no slot; returns the id left in its place.</summary>
    private int WalkAs<T>(JsAst ast, int id) where T : struct, INode<T>
    {
        if (typeof(T) == typeof(Expression)) return Ov(HookExpression) ? CallVisitExpression(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(Statement)) return Ov(HookStatement) ? CallVisitStatement(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(Pattern)) return Ov(HookPattern) ? CallVisitPattern(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(Property)) return Ov(HookProperty) ? CallVisitProperty(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(PropertyName)) return Ov(HookPropertyName) ? CallVisitPropertyName(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(MemberProperty)) return Ov(HookMemberProperty) ? CallVisitMemberProperty(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(ClassElement)) return Ov(HookClassElement) ? CallVisitClassElement(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(PatternProperty)) return Ov(HookPatternProperty) ? CallVisitPatternProperty(ast, id, 0, 0) : Walk(this, ast, id, 0, 0);
        if (typeof(T) == typeof(ConciseBody)) return Ov(HookConciseBody) ? CallVisitConciseBody(ast, id, 0, 0) : WalkConciseBodyVariants(this, ast, id, 0, 0);
        if (typeof(T) == typeof(ForInit)) return Ov(HookForInit) ? CallVisitForInit(ast, id, 0, 0) : WalkForInitVariants(this, ast, id, 0, 0);
        if (typeof(T) == typeof(ForInto)) return Ov(HookForInto) ? CallVisitForInto(ast, id, 0, 0) : WalkForIntoVariants(this, ast, id, 0, 0);
        return Walk(this, ast, id, 0, 0);
    }

